1	# One-shot D-drive consolidation worker.
2	# Triggered by session-start.ps1 when D:\.claude or D:\.claude-data is detected.
3	# Idempotent: a marker file prevents re-runs after success. Designed to be spawned
4	# detached so SessionStart returns quickly while migration completes in background.
5	
6	[CmdletBinding()]
7	param(
8	    [switch]$VerifyOnly
9	)
10	
11	$ErrorActionPreference = 'Continue'
12	
13	$ClaudeRoot = Join-Path $env:USERPROFILE '.claude'
14	$marker     = Join-Path $ClaudeRoot '.consolidation-done'
15	$auditLog   = Join-Path $ClaudeRoot 'cleanup.log'
16	$archiveDir = Join-Path $env:USERPROFILE '.claude-archive'
17	
18	$names = @(
19	    'projects','file-history','shell-snapshots','backups','plans','reports',
20	    'sessions','session-env','paste-cache','downloads','telemetry','cache',
21	    '.docs-cache','.drift-queue'
22	)
23	
24	function Write-Audit {
25	    param([string]$Line)
26	    $ts = Get-Date -Format 'yyyy-MM-dd HH:mm'
27	    "[$ts] oneshot-consolidate: $Line" | Add-Content -Path $auditLog -ErrorAction SilentlyContinue
28	}
29	
30	function Test-DRemnants {
31	    return (Test-Path 'D:\.claude') -or
32	           (Test-Path 'D:\.claude-data') -or
33	           ((Get-ChildItem 'D:\' -Filter 'backup-claude-*.zip' -ErrorAction SilentlyContinue).Count -gt 0) -or
34	           (Test-Path 'D:\migration-tmp')
35	}
36	
37	function Get-VerificationReport {
38	    $report = [ordered]@{}
39	    $report['D:\.claude exists']           = Test-Path 'D:\.claude'
40	    $report['D:\.claude-data exists']      = Test-Path 'D:\.claude-data'
41	    $report['D:\migration-tmp exists']     = Test-Path 'D:\migration-tmp'
42	    $backups = Get-ChildItem 'D:\' -Filter 'backup-claude-*.zip' -ErrorAction SilentlyContinue
43	    $report['D backup zips']               = $backups.Count
44	
45	    $envUser    = [System.Environment]::GetEnvironmentVariable('CLAUDE_CONFIG_DIR','User')
46	    $envMachine = [System.Environment]::GetEnvironmentVariable('CLAUDE_CONFIG_DIR','Machine')
47	    $report['env CLAUDE_CONFIG_DIR User']    = if ($envUser)    { $envUser }    else { '<null>' }
48	    $report['env CLAUDE_CONFIG_DIR Machine'] = if ($envMachine) { $envMachine } else { '<null>' }
49	
50	    $junctionCount = 0
51	    foreach ($n in $names) {
52	        $p = Join-Path $ClaudeRoot $n
53	        if (Test-Path $p) {
54	            $item = Get-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue
55	            if ($item -and $item.LinkType -eq 'Junction') { $junctionCount++ }
56	        }
57	    }
58	    $report['junctions on C']                = $junctionCount
59	
60	    $report['marker .consolidation-done']    = Test-Path $marker
61	    return $report
62	}
63	
64	# Verify-only path: report and exit
65	if ($VerifyOnly) {
66	    Get-VerificationReport | Format-Table -AutoSize
67	    return
68	}
69	
70	# Skip if marker present AND no D remnants
71	if ((Test-Path $marker) -and -not (Test-DRemnants)) {
72	    return
73	}
74	
75	# Defensive: clear inherited env var so child commands resolve to default location
76	Remove-Item Env:CLAUDE_CONFIG_DIR -ErrorAction SilentlyContinue
77	
78	Write-Audit 'starting consolidation'
79	
80	# Phase 0.A — safety net: snapshot current D:\.claude-data\ before destructive moves
81	if (-not (Test-Path $archiveDir)) {
82	    New-Item -ItemType Directory -Force -Path $archiveDir | Out-Null
83	}
84	$rollbackZip = Join-Path $archiveDir 'rollback-pre-consolidation.zip'
85	if ((Test-Path 'D:\.claude-data') -and -not (Test-Path $rollbackZip)) {
86	    try {
87	        Compress-Archive -Path 'D:\.claude-data\*' -DestinationPath $rollbackZip -CompressionLevel Optimal -Force -ErrorAction Stop
88	        Write-Audit "rollback zip created: $rollbackZip"
89	    } catch {
90	        Write-Audit "rollback zip FAIL: $($_.Exception.Message); aborting"
91	        return
92	    }
93	}
94	
95	# Phase 0.B — junction removal + data move (D -> C)
96	$movedCount = 0
97	foreach ($n in $names) {
98	    $cPath = Join-Path $ClaudeRoot $n
99	    $dPath = Join-Path 'D:\.claude-data' $n
100	
101	    if (Test-Path $cPath) {
102	        $item = Get-Item -LiteralPath $cPath -Force -ErrorAction SilentlyContinue
103	        if ($item.LinkType -eq 'Junction') {
104	            try {
105	                & cmd.exe /c "rmdir `"$cPath`"" 2>&1 | Out-Null
106	            } catch {
107	                Write-Audit "junction rmdir FAIL [$n]: $($_.Exception.Message)"
108	                continue
109	            }
110	        }
111	    }
112	
113	    if (Test-Path $dPath) {
114	        try {
115	            $rcArgs = @($dPath, $cPath, '/MOVE', '/E', '/R:2', '/W:1', '/NFL', '/NDL', '/NJH', '/NJS', '/NP')
116	            & robocopy.exe @rcArgs | Out-Null
117	            $movedCount++
118	        } catch {
119	            Write-Audit "robocopy FAIL [$n]: $($_.Exception.Message)"
120	        }
121	    } else {
122	        if (-not (Test-Path $cPath)) {
123	            New-Item -ItemType Directory -Force -Path $cPath | Out-Null
124	        }
125	    }
126	}
127	Write-Audit "moved $movedCount/$($names.Count) data dirs from D to C"
128	
129	# Phase 0.C — D-drive cleanup
130	$cleanupTargets = @(
131	    'D:\.claude'
132	    'D:\.claude-data'
133	    'D:\migration-tmp'
134	)
135	foreach ($t in $cleanupTargets) {
136	    if (Test-Path $t) {
137	        try {
138	            Remove-Item -LiteralPath $t -Recurse -Force -ErrorAction Stop
139	            Write-Audit "deleted: $t"
140	        } catch {
141	            Write-Audit "delete FAIL [$t]: $($_.Exception.Message)"
142	        }
143	    }
144	}
145	
146	# Move D backup zips to C archive
147	Get-ChildItem 'D:\' -Filter 'backup-claude-*.zip' -ErrorAction SilentlyContinue | ForEach-Object {
148	    $dst = Join-Path $archiveDir $_.Name
149	    try {
150	        Move-Item -LiteralPath $_.FullName -Destination $dst -Force -ErrorAction Stop
151	        Write-Audit "archived backup: $($_.Name)"
152	    } catch {
153	        Write-Audit "backup archive FAIL [$($_.Name)]: $($_.Exception.Message)"
154	    }
155	}
156	
157	# Recycle Bin claude artifacts (best effort)
158	try {
159	    Get-ChildItem 'D:\$RECYCLE.BIN' -Recurse -Force -ErrorAction SilentlyContinue |
160	        Where-Object { $_.Name -match 'claude' } |
161	        Remove-Item -Force -Recurse -ErrorAction SilentlyContinue
162	} catch {}
163	
164	# Phase 6 — env var defensive removal (in case it got reset somehow)
165	try { [System.Environment]::SetEnvironmentVariable('CLAUDE_CONFIG_DIR', $null, 'User') } catch {}
166	
167	# Bump prefix-version.txt to invalidate prompt cache after structural change
168	try {
169	    $cacheDir = Join-Path $ClaudeRoot '.docs-cache'
170	    if (-not (Test-Path $cacheDir)) { New-Item -ItemType Directory -Force -Path $cacheDir | Out-Null }
171	    $pvFile = Join-Path $cacheDir 'prefix-version.txt'
172	    $newVer = 1
173	    $newTicks = (Get-Date).Ticks
174	    if (Test-Path $pvFile) {
175	        $prev = (Get-Content $pvFile -Raw -ErrorAction SilentlyContinue).Trim() -split '\s+'
176	        if ($prev.Count -ge 1) { [void][long]::TryParse($prev[0], [ref]$newVer); $newVer++ }
177	    }
178	    Set-Content -Path $pvFile -Value "$newVer $newTicks" -Encoding UTF8 -NoNewline
179	} catch {}
180	
181	# Final state check
